select

from survey_consignor_price
where  delete_flag = 0

    and entury_id = #{enturyId,jdbcType=BIGINT}


    and task_id = #{taskId,jdbcType=BIGINT}


    and area_id = #{areaId,jdbcType=INTEGER}


    and city_type = #{cityType,jdbcType=INTEGER}


    and task_info_content_id = #{taskInfoContentId,jdbcType=BIGINT}


    and direction_result_type_id = #{directionResultTypeId,jdbcType=BIGINT}

limit 1;
